For all $n, T > 0$, there exists a principal-agent problem $\left(\bm{c}, \bm{F}, \bm{r}\right)$ with $T$ types, $n+1$ actions, and two outcomes that satisfies
\begin{align*}
  \textsc{Opt-Linear} \left(\bm{c}, \bm{F}, \bm{r}\right) \le O\left( \frac{1}{n \log T} \right) \textsc{Welfare} \left(\bm{c}, \bm{F}, \bm{r}\right)
  \text{.}
\end{align*}

For all $n, T > 0$, there exists a principal-agent problem $\left(\bm{c}, \bm{F}, \bm{r}\right)$ with $T$ types, $n+1$ actions, and two outcomes that satisfies
\begin{align*}
  \textsc{Opt-Menu} \left(\bm{c}, \bm{F}, \bm{r}\right) \le O\left( \frac{1}{n \log T} \right) \textsc{Welfare} \left(\bm{c}, \bm{F}, \bm{r}\right)
  \text{.}
\end{align*}

For all $n, T > 0$, there exists a principal-agent problem $\left(\bm{c}, \bm{F}, \bm{r}\right)$ with $T$ types, $n+1$ actions, and four outcomes that satisfies
\begin{align*}
  \textsc{Opt-Linear} \left(\bm{c}, \bm{F}, \bm{r}\right) \le O\left( \frac{1}{n \log T} \right) \textsc{Opt-Single} \left(\bm{c}, \bm{F}, \bm{r}\right)
  \text{.}
\end{align*}

For all $n, T > 0$, there exists a principal-agent problem $\left(\bm{c}, \bm{F}, \bm{r}\right)$ with $T+1$ types, $n+1$ actions, and four outcomes that satisfies
\begin{align*}
  \textsc{Opt-Menu} \left(\bm{c}, \bm{F}, \bm{r}\right) \le O\left( \frac{1}{n \log T} \right) \textsc{Opt-TypeAware} \left(\bm{c}, \bm{F}, \bm{r}\right)
  \text{.}
\end{align*}
